-- v1 baseline — squash of the 124 pre-v1.0.0 migrations (2026-08).
-- Generated by replaying the full migration history into a clean PostGIS
-- container and diffing the result (prisma migrate diff --from-empty --to-url),
-- then appending what the differ cannot express:
--   * CREATE EXTENSION statements (prisma migrate diff never emits them);
--   * the reference rows that survive a clean replay (retention configs,
--     PII field mappings, platform notification templates) — platform config
--     every environment needs, production included.
-- Verified by replay-diff: old-history DB vs baseline DB produce an empty
-- prisma migrate diff and identical data dumps.
-- Pre-existing environments were baselined with `prisma migrate resolve`.

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pg_trgm;

