INSERT INTO notification_templates VALUES ('0d16f1ed-dec6-4140-a63e-05077a98c84e', NULL, 'TENANT_NOTICE_FORWARDED_AGENCY', 'EMAIL', 'Tenant notice not sent - {{propertyAddress}}', '<p>Your agency contacts tenants directly, so Properfy did not send "{{suppressedTemplateLabel}}" for inspection {{appointmentCode}} at {{propertyAddress}} on {{scheduledDate}}. Please pass it on to the tenant.</p>', 'Your agency contacts tenants directly, so Properfy did not send "{{suppressedTemplateLabel}}" for inspection {{appointmentCode}} at {{propertyAddress}} on {{scheduledDate}}. Please pass it on to the tenant.', '["suppressedTemplateLabel", "suppressedChannel", "propertyAddress", "appointmentCode", "scheduledDate"]', true, '2026-08-06 13:10:23.428', '2026-08-06 13:10:23.428', 'TRANSACTIONAL');
INSERT INTO notification_templates VALUES ('e43f45b1-264d-47c5-ba7c-4c1d03f25c6b', NULL, 'INSPECTION_SATISFACTION_SURVEY', 'EMAIL', 'How did your inspection go?', '<p>Your inspection has been completed. Tell us how it went: <a href="{{surveyLink}}">Rate your inspection</a></p>', 'Your inspection has been completed. Tell us how it went: {{surveyLink}}', '["surveyLink"]', true, '2026-08-06 13:10:23.471', '2026-08-06 13:10:23.471', 'OPERATIONAL');
